() => {
  // Find all ratings in the visible search results panel
  const results = [];
  const allLinks = document.querySelectorAll('a[aria-label]');
  for (const link of allLinks) {
    const label = link.getAttribute('aria-label');
    if (label && !label.includes('Facebook') && !label.includes('Twitter') && !label.includes('Google')) {
      // Look for ratings within or near the link
      let rating = null;
      let reviews = null;
      const ratingEl = link.querySelector('[role="img"][aria-label*="星级"]');
      if (ratingEl) {
        const ratingLabel = ratingEl.getAttribute('aria-label');
        const match = ratingLabel.match(/(\d+\.\d+)\s*星级\s*(\d+)条评价/);
        if (match) {
          rating = parseFloat(match[1]);
          reviews = parseInt(match[2]);
        }
      }
      // Check if this looks like a salon (not ad)
      const isAd = link.querySelector('[aria-label*="赞助商"]') !== null;
      // Get category text
      const categoryEl = link.querySelector('span:not([role="img"])');
      let category = '';
      link.querySelectorAll('span').forEach(s => {
        const t = s.textContent;
        if (t.includes('沙龙') || t.includes('美容') || t.includes('spa') || t.includes('Spa')) {
          category = t.substring(0, 50);
        }
      });
      results.push({
        name: label.substring(0, 60),
        rating,
        reviews,
        isAd,
        category
      });
    }
  }
  return results;
}

() => {
  // Find all the salon result items
  const resultItems = document.querySelectorAll('div[role="feed"] > div > div > a, div[role="main"] a[aria-label]');
  // Use __find to find all entries with ratings
  const ratings = document.querySelectorAll('[role="img"][aria-label*="星级"]');
  const results = [];
  for (const rating of ratings) {
    const label = rating.getAttribute('aria-label');
    const match = label.match(/(\d+\.\d+)\s*星级\s*(\d+)条评价/);
    if (match) {
      // Find the nearest link with a label
      let parent = rating;
      let name = '';
      let category = '';
      while (parent && !name) {
        parent = parent.parentElement;
        if (parent) {
          const link = parent.querySelector('a[aria-label]:not([aria-label*="路线"]):not([aria-label*="保存"])');
          if (link) {
            name = link.getAttribute('aria-label');
          }
        }
      }
      // Find category text near this rating
      let sibling = rating.nextElementSibling;
      const spans = parent?.querySelectorAll('span') || [];
      for (const s of spans) {
        const t = s.textContent;
        if (t.match(/美容|沙龙|spa|Spa/)) {
          category = t.substring(0, 80);
        }
      }
      results.push({
        rating: parseFloat(match[1]),
        reviews: parseInt(match[2]),
        name,
        category
      });
    }
  }
  return results;
}

