(() => {
  const links = document.querySelectorAll('a[aria-label]');
  const result = [];
  for (const link of links) {
    const name = link.getAttribute('aria-label');
    if (name.includes('Salon') || name.includes('Beauty') || name.includes('Spa')) {
      // Look for a rating element near this link
      let parent = link;
      for (let i = 0; i < 5 && parent; i++) {
        parent = parent.parentElement;
        if (!parent) break;
      }
      if (parent) {
        const ratingEl = parent.querySelector('[role="img"][aria-label*="星级"]');
        if (ratingEl) {
          const label = ratingEl.getAttribute('aria-label');
          result.push({name, rating: label});
        } else {
          result.push({name, rating: 'NO_RATING_VISIBLE'});
        }
      }
    }
  }
  return result;
})()

